EDITS = {'CHANGELOG.md': [('lines 4-5', 'versioning follows [SemVer](https://semver.org/).\n\n', "versioning follows [SemVer](https://semver.org/).\n\n## [0.40.0] - grime along every ground storey's base\n\nThe factory's roadmap 324. A real wall darkens from the ground up; the slice's walls met the sidewalk clean.\n\n### Added\n- **`framing.base_grime_orders`**: a `stain_base` along each SPAN of a ground storey's side -- consecutive exterior\n  slots of wall, not glass, none of whose openings comes below `GRIME_CLEAR` -- from the storey's foot up `GRIME_H`\n  (0.5-0.85 m, seeded; 0.45-0.7 read as a sliver at the wall's foot on slice 18b). One order a span, so no seam shows\n  at a module joint and the band fades only at a corner or an opening; a door, a garage, a breach and a storefront\n  end it, and a window whose sill is above the band keeps it under. A span under `GRIME_MIN_SPAN` (0.6 m) is a pier\n  and gets none. In the run's wall kind. `_run_kinds` is the run-kind lookup `stain_orders` did inline, now shared.\n  The CLI adds them after the window stains.\n- **`openings.EXEMPT`** gains `stain_base`, the eleventh: a span ends at a door's jamb, inside the door's margin,\n  where real grime is heaviest.\n\nOn the slice (slices 18-20): 228 orders across the avenue, about 114 distinct; the bank's street front is a\nstorefront and gets none. Priced on slice 18 against slice 17e: draws median +0, largest +2. Tests:\ntests/test_base_grime.py, tests/test_openings.py (the exemptions are eleven).\n\n")], 'VERSION': [('lines 1-1', 'Patina 0.39.0', 'Patina 0.40.0')], 'patina/cli.py': [('lines 476-477', "                    slot_manifest, regions, seed=args.seed)\n            # The keep-out rule needs DC's openings, which only the slot\n", "                    slot_manifest, regions, seed=args.seed)\n                # and grime along every ground storey's base (0.40.0)\n                panels += framing.base_grime_orders(\n                    slot_manifest, regions, seed=args.seed)\n            # The keep-out rule needs DC's openings, which only the slot\n")], 'patina/framing.py': [('lines 835-842', '    runs: dict = {}\n    for w in manifest.slots:\n        sid = str(w.slot_id)\n        # a run\'s glass is its storefront, not its wall: a stain is never laid in it\n        if w.role == "wall" and sid.startswith("ext_") and w.material and "glass" not in str(w.material):\n            key = "_".join(sid.split("_")[:3])\n            runs.setdefault(key, {}).setdefault(w.material, 0)\n            runs[key][w.material] += 1\n', '    runs = _run_kinds(manifest)\n'), ('lines 847-848', '        kinds = runs.get("_".join(str(s.slot_id).split("_")[:3]))\n        if not kinds:\n', '        kind = runs.get("_".join(str(s.slot_id).split("_")[:3]))\n        if not kind:\n'), ('lines 850-850', '        kind = sorted(kinds.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]\n', ''), ('lines 882-883', '                orders.append(order)\n    return orders\n', '                orders.append(order)\n    return orders\n\n\ndef _run_kinds(manifest: SlotManifest) -> dict:\n    """``{"ext_<storey>_<side>": kind}``: the commonest material kind among a run\'s `wall` slots, ties broken by name.\n    A run\'s glass is its storefront, not its wall, and a stain is never laid in it."""\n    counts: dict = {}\n    for w in manifest.slots:\n        sid = str(w.slot_id)\n        if w.role == "wall" and sid.startswith("ext_") and w.material and "glass" not in str(w.material):\n            key = "_".join(sid.split("_")[:3])\n            counts.setdefault(key, {}).setdefault(w.material, 0)\n            counts[key][w.material] += 1\n    return {k: sorted(v.items(), key=lambda kv: (-kv[1], kv[0]))[0][0] for k, v in counts.items()}\n\n\n#: GRIME AT A WALL\'S BASE (0.40.0, Zoo >= 1.154.0 builds it, Level Factory >= 0.271.0 draws it). Rain splashes back\n#: off the ground and damp rises: a real wall darkens from the ground up, and the slice\'s walls met the sidewalk\n#: clean. A `stain_base` order runs along each SPAN of a ground storey\'s side -- consecutive exterior slots of wall,\n#: not glass, none of whose openings comes below `GRIME_CLEAR` (a door, a garage, a breach, a storefront end it; a\n#: window whose sill is above the band keeps it under) -- from the storey\'s foot up `GRIME_H` (seeded between its bounds; Zoo\n#: lifts each column to its own share of it). One order a span, so no seam shows at a module joint and the band\n#: fades only at the span\'s own ends, at a corner or an opening. In the run\'s wall kind, as a stain under a sill.\n#: 0.45-0.7 m read as a sliver at the wall\'s foot (the factory\'s slice 18b); splash-back and rising damp reach higher\nGRIME_H = (0.5, 0.85)\nGRIME_CLEAR = GRIME_H[1] + 0.05\n#: a span shorter than this is a pier between openings, and gets none\nGRIME_MIN_SPAN = 0.6\n#: slots closer than this along their side are one span\nGRIME_JOIN = 0.02\n\n\ndef base_grime_orders(manifest: SlotManifest, regions: list, *, seed: int) -> list[dict]:\n    """A `stain_base` along each span of every ground storey side, between its corners and its low openings."""\n    center = footprint_center(manifest)\n    thick_m = modal_thickness(manifest)\n    runs = _run_kinds(manifest)\n    sides: dict = {}\n    for s in manifest.slots:\n        sid = str(s.slot_id)\n        if not sid.startswith("ext_0_") or not s.dims:\n            continue\n        sides.setdefault("_".join(sid.split("_")[:3]), []).append(s)\n    orders = []\n    for key in sorted(sides):\n        kind = runs.get(key)\n        if not kind:\n            continue\n        group = sides[key]\n        first = group[0]\n        frame0 = wall_frame(first, center, thick_m)\n        along = frame0[2]\n        x0, y0 = float(first.translation[0]), float(first.translation[1])\n        spans = []\n        for s in group:\n            run = wall_frame(s, center, thick_m)[0]\n            p = (float(s.translation[0]) - x0) * along[0] + (float(s.translation[1]) - y0) * along[1]\n            low = any(float(op.get("sill", 0.0)) < GRIME_CLEAR for op in s.openings)\n            # a storefront\'s or a glass facade\'s module is glass to its foot: grime is never laid on a pane\n            glass = "glass" in str(s.material) or s.glazing == "storefront"\n            spans.append((p - run / 2.0, p + run / 2.0, not (low or glass), s))\n        spans.sort(key=lambda r: (r[0], r[1]))\n        merged = []\n        for a, b, ok, s in spans:\n            if not ok:\n                merged.append(None)\n                continue\n            if merged and merged[-1] is not None and a - merged[-1][1] < GRIME_JOIN:\n                merged[-1][1] = max(merged[-1][1], b)\n            else:\n                merged.append([a, b, s])\n        k = 0\n        for m in merged:\n            if m is None or m[1] - m[0] < GRIME_MIN_SPAN:\n                continue\n            a, b, s = m\n            rng = rng_for(seed, "grime", key, str(k))\n            k += 1\n            height = float(rng.uniform(*GRIME_H))\n            pos, n = _face(first, (a + b) / 2.0, _base_z(s), frame0)\n            orders.append({\n                "anchor_kind": "stain", "cover": "stain_base", "collision": "none",\n                "trim_piece": None, "uv_region": None, "slot_id": s.slot_id,\n                "wall_material": kind,\n                "pos": pos, "normal": n,\n                "size": round(b - a, 3), "size2": [round(b - a, 3), round(height, 3)],\n                "seed_offset": int(rng.integers(0, 1_000_000)),\n            })\n    return orders\n')], 'patina/openings.py': [('lines 62-62', "#: keeps it clear of every door's, garage's and breach's lane itself.\n", "#: keeps it clear of every door's, garage's and breach's lane itself. A `stain_base` (0.40.0) is the same skin along\n#: a wall's foot, and `framing.base_grime_orders` ends it at every opening that comes down into its band -- right\n#: beside the jamb, inside that opening's margin, where real grime is heaviest.\n"), ('lines 64-64', '          "tv_antenna", "sat_dish", "coping", "stain_streak")\n', '          "tv_antenna", "sat_dish", "coping", "stain_streak", "stain_base")\n')], 'patina/version.py': [('lines 9-9', '__version__ = "0.39.0"\n', '__version__ = "0.40.0"\n')], 'tests/test_openings.py': [('lines 91-91', 'def test_the_exemptions_are_the_listed_ten():\n', 'def test_the_exemptions_are_the_listed_eleven():\n'), ('lines 106-106', '                               "stain_streak"), \\\n', '                               "stain_streak", "stain_base"), \\\n')]}
